select FileProject,
wm_concat((select top 1 T_Code from ${tableCode} where FileProject=t1.FileProject and
FileFlowStatus=7 order by FileCreateDate desc )) as tcode
from (select * from SYS_File where FileCreateUser=#{uId}

    and T_Code in
    
        #{tCode}
    


    and Te_Id = #{teId}

and FileProject is not null)t1
group by t1.FileProject

select FileProject,
string_agg((select top 1 T_Code from ${tableCode} where FileProject=t1.FileProject and
FileFlowStatus=7 order by FileCreateDate desc ),',') as tcode
from (select * from SYS_File where FileCreateUser=#{uId}

    and T_Code in
    
        #{tCode}
    


    and Te_Id = #{teId}

and FileProject is not null)t1
group by t1.FileProject

select FileProject,
GROUP_CONCAT((select T_Code from ${tableCode} where FileProject=t1.FileProject and
FileFlowStatus=7 order by FileCreateDate desc  limit 1)) as tcode
from (select * from SYS_File where FileCreateUser=#{uId}

    and T_Code in
    
        #{tCode}
    


    and Te_Id = #{teId}

and FileProject is not null)t1
group by t1.FileProject

